package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import java.time.temporal.Temporal
import scala.util.Try
import io.circe._
import scala.collection.mutable

// ============================================================================ 
// Enums and Constants
// ============================================================================ 

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================ 
// Protocols (Traits in Scala)
// ============================================================================ 

trait Tokenizable {
  def toToken(): String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================ 
// Core Token Classes
// ============================================================================ 

case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(kwargs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kwargs.toMap)
  }
}

class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer.empty[Token]
  private var _processed = false

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def tokens: List[Token] = _tokens.toList
}

// ============================================================================ 
// Generic Container Classes
// ============================================================================ 

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): List[String] = _items.map(func).toList

  def size: Int = _items.size
}

class TokenSink[-T] {
  private val received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

class BivariantHandler[T](private var _value: T) {
  def get: T = _value
  def set(value: T): Unit = {
    _value = value
  }
  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================ 
// Tokenizer Implementations
// ============================================================================ 

trait BaseTokenizer[T] {
  def tokenize(value: T): Token
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = values.iterator.map(tokenize)
}

class StringTokenizer(
  val encoding: String = "utf-8",
  val normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s) => s
      case Right(b) => new String(b, encoding)
    }
    Token(normalizer(strValue), TokenType.STRING)
  }
}

class NumericTokenizer[T](
  val precision: Int = 6,
  val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[T] {

  override def tokenize(value: T): Token = {
    val strValue = value match {
      case d: BigDecimal => d.setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString
      case d: Double => s"%.${precision}f".format(d)
      case f: Float => s"%.${precision}f".format(f)
      case _ => value.toString
    }
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

class TemporalTokenizer(val formatStr: Option[String] = None) extends BaseTokenizer[Temporal] {
  val ISO_FORMAT = "yyyy-MM-dd'T'HH:mm:ss"
  val DATE_FORMAT = "yyyy-MM-dd"

  override def tokenize(value: Temporal): Token = {
    val fmtStr = formatStr.getOrElse {
      value match {
        case _: LocalDateTime => ISO_FORMAT
        case _: LocalDate => DATE_FORMAT
        case _ => ISO_FORMAT
      }
    }
    val formatter = DateTimeFormatter.ofPattern(fmtStr)
    Token(formatter.format(value), TokenType.TEMPORAL)
  }
}

// ============================================================================ 
// Universal Tokenizer
// ============================================================================ 

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer[Any]()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => Token(t.toToken(), TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(Left(s))
    case b: Array[Byte] => stringTokenizer.tokenize(Right(b))
    case i: Int => numericTokenizer.tokenize(i)
    case l: Long => numericTokenizer.tokenize(l)
    case d: Double => numericTokenizer.tokenize(d)
    case f: Float => numericTokenizer.tokenize(f)
    case bd: BigDecimal => numericTokenizer.tokenize(bd)
    case t: Temporal => temporalTokenizer.tokenize(t)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================ 
// Token Registry
// ============================================================================ 

class TokenRegistry[T] {
  private val _registry = mutable.Map.empty[String, TokenContainer[T]]
  private val _handlers = mutable.ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case Some(container) =>
        container.getAll.toList.map {
          item =>
          _handlers.to(LazyList).flatMap(h => h(item)).headOption
        }
      case None => Nil
    }
  }
}

// ============================================================================ 
// Token Functor / Monad
// ============================================================================ 

class TokenFunctor[T](val value: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(value))
  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(value)
  def get: T = value
  def getOrElse(default: T): T = if (value != null) value else default
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get(value))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================ 
// JSON Tokenizer
// ============================================================================ 

class JsonTokenizer(val pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split('.')
    val found = parts.foldLeft(Option(value)) { (current, part) =>
      current.flatMap {
        c =>
        c.asObject.flatMap(_.apply(part)).orElse {
          Try(part.toInt).toOption.flatMap(idx => c.asArray.flatMap(arr => if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None))
        }
      }
    }
    found.map(tokenize)
  }
}

// ============================================================================ 
// Whitespace Tokenizer
// ============================================================================ 

class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var w = word
    if (stripPunctuation) {
      w = w.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }
    if (lowercase) {
      w = w.toLowerCase
    }
    if (w.length < minLength) return None
    maxLength.foreach {
      max =>
      if (w.length > max) w = w.substring(0, max)
    }
    if (w.isEmpty) None else Some(w)
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").filter(_.nonEmpty).zipWithIndex.flatMap {
      case (word, i) =>
      processToken(word).map {
        processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var currentPos = 0
    text.split("\\s+").filter(_.nonEmpty).flatMap {
      word =>
      val start = text.indexOf(word, currentPos)
      if (start == -1) None
      else {
        val end = start + word.length
        currentPos = end
        processToken(word).map {
          processed =>
          (processed, start, end)
        }
      }
    }.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

